import React, { useState, useEffect } from 'react';
import API from '../services/api';

function Dashboard() {
    const [subscriptions, setSubscriptions] = useState([]);
    const [analytics, setAnalytics] = useState([]);
    const [actionable, setActionable] = useState([]);
    const [showAddForm, setShowAddForm] = useState(false);
    const [newSub, setNewSub] = useState({ name: '', cost: '', billingCycle: 'monthly', usageFrequency: 50 });

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        const [subsRes, analyticsRes, actionableRes] = await Promise.all([
            API.get('/subscriptions'),
            API.get('/subscriptions/analytics/spending-by-classification'),
            API.get('/subscriptions/analytics/actionable')
        ]);
        setSubscriptions(subsRes.data);
        setAnalytics(analyticsRes.data);
        setActionable(actionableRes.data);
    };

    const addSubscription = async (e) => {
        e.preventDefault();
        await API.post('/subscriptions', newSub);
        fetchData();
        setShowAddForm(false);
        setNewSub({ name: '', cost: '', billingCycle: 'monthly', usageFrequency: 50 });
    };

    const deleteSubscription = async (id) => {
        if (window.confirm('Delete this subscription?')) {
            await API.delete(`/subscriptions/${id}`);
            fetchData();
        }
    };

    const getColorForClassification = (classification) => {
        const colors = {
            waste: '#dc3545',
            expensive: '#fd7e14',
            infrequent: '#ffc107',
            essential: '#28a745',
            good_value: '#17a2b8',
            pending: '#6c757d'
        };
        return colors[classification] || '#6c757d';
    };

    return (
        <div className="dashboard">
            <header>
                <h1>📊 Subscription Analyzer</h1>
                <button className="add-btn" onClick={() => setShowAddForm(!showAddForm)}>+ Add Subscription</button>
            </header>

            {showAddForm && (
                <form className="add-form" onSubmit={addSubscription}>
                    <input placeholder="Name (Netflix, Spotify...)" value={newSub.name} onChange={(e) => setNewSub({...newSub, name: e.target.value})} required />
                    <input type="number" placeholder="Monthly Cost ($)" value={newSub.cost} onChange={(e) => setNewSub({...newSub, cost: e.target.value})} required />
                    <select value={newSub.billingCycle} onChange={(e) => setNewSub({...newSub, billingCycle: e.target.value})}>
                        <option value="monthly">Monthly</option>
                        <option value="yearly">Yearly</option>
                        <option value="weekly">Weekly</option>
                    </select>
                    <label>Usage Frequency: {newSub.usageFrequency}%</label>
                    <input type="range" min="0" max="100" value={newSub.usageFrequency} onChange={(e) => setNewSub({...newSub, usageFrequency: parseInt(e.target.value)})} />
                    <button type="submit">Save & Classify</button>
                </form>
            )}

            <div className="analytics-section">
                <h3>💰 Spending by Classification</h3>
                <div className="analytics-cards">
                    {analytics.map(a => (
                        <div key={a._id} className="analytic-card" style={{borderLeft: `4px solid ${getColorForClassification(a._id)}`}}>
                            <h4>{a._id || 'Unclassified'}</h4>
                            <p>Total: ${a.totalCost}/month</p>
                            <small>{a.count} subscriptions | Avg: ${a.avgCost}</small>
                        </div>
                    ))}
                </div>
            </div>

            {actionable.length > 0 && (
                <div className="actionable-section">
                    <h3>⚠️ Action Needed! {actionable.length} subscriptions to review</h3>
                    <div className="subscription-list">
                        {actionable.map(sub => (
                            <div key={sub._id} className="subscription-card actionable" style={{borderColor: getColorForClassification(sub.classification)}}>
                                <h4>{sub.name}</h4>
                                <p>${sub.cost}/month</p>
                                <span className="badge" style={{background: getColorForClassification(sub.classification)}}>{sub.classification}</span>
                                <p>Usage: {sub.usageFrequency}%</p>
                                <button onClick={() => deleteSubscription(sub._id)}>Cancel</button>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="all-subscriptions">
                <h3>All Subscriptions</h3>
                <div className="subscription-list">
                    {subscriptions.map(sub => (
                        <div key={sub._id} className="subscription-card">
                            <h4>{sub.name}</h4>
                            <p>${sub.cost}/month</p>
                            <span className="badge" style={{background: getColorForClassification(sub.classification)}}>{sub.classification}</span>
                            <button onClick={() => deleteSubscription(sub._id)}>Delete</button>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

export default Dashboard;
